import path from "node:path";

// Where uploaded photos live on disk. In Docker this directory is a volume. File names are random and generated by
// the server; the original name of the uploaded file is never used.
export function uploadDir(): string {
  return path.resolve(process.env.UPLOAD_DIR ?? "./uploads");
}

const SAFE_NAME = /^[a-z0-9_-]{8,64}\.(jpg|png|webp)$/;

// Absolute path of an uploaded file, or null when the name is not one of ours (no traversal, no other extension).
export function uploadFilePath(fileName: string): string | null {
  if (!SAFE_NAME.test(fileName)) return null;
  return path.join(uploadDir(), fileName);
}

export function contentTypeFor(fileName: string): string {
  return fileName.endsWith(".png") ? "image/png" : fileName.endsWith(".webp") ? "image/webp" : "image/jpeg";
}

export const MAX_PHOTO_BYTES = 5 * 1024 * 1024;
export const MAX_PHOTOS_PER_VEHICLE = 8;

export type ImageKind = { ext: "jpg" | "png" | "webp"; mime: string };

// The file type is decided by the CONTENT (magic bytes), never by the name or the type the browser claims.
export function sniffImage(bytes: Uint8Array): ImageKind | null {
  if (bytes.length >= 3 && bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff) return { ext: "jpg", mime: "image/jpeg" };
  if (bytes.length >= 8 && bytes[0] === 0x89 && bytes[1] === 0x50 && bytes[2] === 0x4e && bytes[3] === 0x47 && bytes[4] === 0x0d && bytes[5] === 0x0a && bytes[6] === 0x1a && bytes[7] === 0x0a) return { ext: "png", mime: "image/png" };
  if (bytes.length >= 12 && String.fromCharCode(...bytes.slice(0, 4)) === "RIFF" && String.fromCharCode(...bytes.slice(8, 12)) === "WEBP") return { ext: "webp", mime: "image/webp" };
  return null;
}
